def _load_engine():
    """Load encrypted engine"""
    d = zlib.decompress(_E_ENGINE).decode()
    g = {}
    exec(d, g)
    return g["AIDetectionEngine"]()

# License System - Username + Password
_SECRET = "STv35#License2025"

def _load_users_db():
    """تحميل قاعدة بيانات المستخدمين"""
    db_file = ".users_db.json"
    if os.path.exists(db_file):
        try:
            with open(db_file, "r") as f:
                return json.load(f)
        except:
            return {}
    return {}

def _save_users_db(db):
    """حفظ قاعدة بيانات المستخدمين"""
    db_file = ".users_db.json"
    try:
        with open(db_file, "w") as f:
            json.dump(db, f, indent=2)
        return True
    except:
        return False

def _verify_user(username, password):
    """التحقق من username + password"""
    try:
        db = _load_users_db()
        
        # حساب hash للـ username+password
        user_hash = hashlib.sha256(f"{username}:{password}".encode()).hexdigest()
        
        if user_hash not in db:
            return False, "❌ Invalid username or password", 0
        
        user_data = db[user_hash]
        
        # التحقق من تاريخ الانتهاء
        exp = datetime.datetime.strptime(user_data["expires"], "%Y%m%d")
        if datetime.datetime.now() > exp:
            return False, f"❌ License expired on {exp.strftime('%Y-%m-%d')}", 0
        
        d = (exp - datetime.datetime.now()).days
        
        # تحديث آخر دخول
        user_data["last_login"] = datetime.datetime.now().strftime("%Y%m%d%H%M%S")
        db[user_hash] = user_data
        _save_users_db(db)
        
        return True, user_data["name"], d
        
    except Exception as ex:
        return False, f"❌ Error: {str(ex)}", 0

