st.markdown("### 📝 Analyze Text")
txt = st.text_area("Enter text to analyze:", height=200, placeholder="Paste your text here...")

if st.button("🔬 Analyze", type="primary"):
    if len(txt.strip()) < 50:
        st.warning("⚠️ Text too short - enter at least 50 words.")
    else:
        with st.spinner("Analyzing..."):
            eng = _load_engine()
            res = eng.analyze(txt)
            sc = res.get("percentage", 0)
            shu = 100 - sc
            
            col1, col2 = st.columns(2)
            with col1:
                st.metric("🤖 AI Content", f"{sc:.1f}%")
            with col2:
                st.metric("👤 Human Written", f"{shu:.1f}%")
            
            st.success("✅ Analysis complete!")
